universe {
    display: block;
    width: 100vw;
    height: 100vh;
    overflow: hidden;
    position: relative;
    background-image: url('data:image/jpeg;base64,');
    background-repeat: no-repeat;
    background-size: cover;
}

.svg-frame {
    position: relative;
    width: 300px;
    height: 300px;
    transform-style: preserve-3d;
    display: flex;
    justify-content: center;
    align-items: center;
    align-content: center;
}

    .svg-frame svg {
        position: absolute;
        transition: .5s;
        z-index: calc(1 - (0.2 * var(--j)));
        transform-origin: center;
        width: 344px;
        height: 344px;
        fill: none;
    }

    .svg-frame:hover svg {
        transform: rotate(-80deg) skew(30deg) translateX(calc(45px * var(--i))) translateY(calc(-35px * var(--i)));
    }

    .svg-frame svg #center {
        transition: .5s;
        transform-origin: center;
    }

    .svg-frame:hover svg #center {
        transform: rotate(-30deg) translateX(45px) translateY(-3px);
    }

#out2 {
    animation: rotate16 7s ease-in-out infinite alternate;
    transform-origin: center;
}

#out3 {
    animation: rotate16 3s ease-in-out infinite alternate;
    transform-origin: center;
    stroke: #ff0;
}

#inner3,
#inner1 {
    animation: rotate16 4s ease-in-out infinite alternate;
    transform-origin: center;
}

#center1 {
    fill: #ff0;
    animation: rotate16 2s ease-in-out infinite alternate;
    transform-origin: center;
}

@keyframes rotate16 {
    to {
        transform: rotate(360deg);
    }
}


.star {
    position: absolute;
    top: 50%;
    left: 50%;
    width: 4px;
    height: 4px;
    background: linear-gradient(-45deg, rgb(255, 255, 255), rgba(0, 0, 255, 0));
    border-radius: 50%; /*999px;*/
    filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.3)) drop-shadow(0 0 8px rgba(255, 255, 255, 0.3)) drop-shadow(0 0 20px rgba(255, 255, 255, 1));
    /* filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.1)) drop-shadow(0 0 8px rgba(255, 255, 255, 0.1)) drop-shadow(0 0 20px rgba(255, 255, 255, 1)); */
    animation: animate 3s linear infinite;
}

    .star::before, .star::after {
        content: '';
        position: absolute;
        top: calc(50% - 1px);
        right: 0;
        width: 0;
        height: 2px;
        background: linear-gradient(-45deg, rgba(0, 0, 255, 0), rgb(255, 255, 255), rgba(0, 0, 255, 0));
        border-radius: 100%;
        transform: translateX(50%) rotateZ(45deg);
        animation: shining 3s ease-in-out infinite;
    }

    .star::after {
        transform: translateX(50%) rotateZ(-45deg);
    }

    .star:nth-child(1) {
        top: calc(50% - 173px);
        left: calc(50% - 119px);
        width: 6px;
        height: 6px;
        background: linear-gradient(-45deg, rgba(0, 0, 255, 0), rgb(255, 255, 255), rgba(0, 0, 255, 0));
        animation-delay: 0s;
    }

        .star:nth-child(1)::before, .star:nth-child(1)::after {
            font-size: 12px;
            /* animation: none; */
            animation-delay: 0;
        }


@keyframes shining {
    0% {
        width: 0;
    }

    50% {
        width: 50px;
    }

    100% {
        width: 0;
    }
}

@keyframes animate {
    0% {
        width: 0px;
        transform: rotate(45deg) translateX(0);
        opacity: 0.4;
    }

    50% {
        width: 100px;
        opacity: 0.7;
    }

    100% {
        width: 0px;
        /* Giảm khoảng cách di chuyển để phù hợp màn hình */
        transform: rotate(45deg) translateX(50vw);
        opacity: 0;
    }
}

.spaceship {
    position: absolute;
    width: 100px;
    height: 100px;
    /* border-radius: 50% 50% 10% 10%; */
    background: url('data:image/png;base64,') no-repeat center center;
    background-size: contain;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%) rotateZ(45deg);
    transition: all 0.3s ease;
    z-index: 10;
}

    .spaceship::before, .spaceship::after {
        content: '';
        position: absolute;
        width: 10px;
        height: 10px;
        background: radial-gradient(circle, rgba(255, 255, 255, 0.8), rgba(255, 255, 255, 0));
        border-radius: 50%;
        top: 20px;
        left: 70px;
    }

    .spaceship::after {
        width: 30px;
        background: linear-gradient(to right, rgba(255, 165, 0, 0.8), rgba(255, 0, 0, 0));
        top: 80px;
        left: 0px;
        animation: flame 0.5s ease-in-out infinite;
    }

@keyframes flame {
    0% {
        transform: scale(1) rotate(-45deg);
        opacity: 0.7;
    }

    50% {
        transform: scale(1.2) rotate(-45deg);
        opacity: 1;
    }

    100% {
        transform: scale(1) rotate(-45deg);
        opacity: 0.7;
    }
}


